const item = $input.first().json;

const sourceAccount = item.sourceAccount;
const subject = item.subject || item.headers?.subject || '(no subject)';

let senderEmail = '';
let senderName = '';
if (item.from?.value?.[0]) {
  senderEmail = item.from.value[0].address || '';
  senderName = item.from.value[0].name || '';
} else if (typeof item.from === 'string') {
  const match = item.from.match(/<([^>]+)>/);
  senderEmail = match ? match[1] : item.from;
  senderName = item.from.replace(/<[^>]+>/, '').trim();
}

const messageId =
  item.messageId ||
  item.id ||
  item.headers?.['message-id'] ||
  item.headers?.['Message-ID'] ||
  `${sourceAccount}-${Date.now()}`;

const rawDate = item.date || item.internalDate || new Date().toISOString();
const receivedAt = new Date(rawDate).toISOString();

const body = (
  item.textPlain ||
  item.text ||
  item.snippet ||
  item.html ||
  ''
).toString().slice(0, 12000);

const attachments = item.attachments || [];
const attachmentNames = attachments
  .map((a) => a.filename || a.name)
  .filter(Boolean);

return [
  {
    json: {
      sourceAccount,
      externalMessageId: messageId,
      senderEmail: senderEmail || 'unknown@unknown.com',
      senderName,
      subject,
      receivedAt,
      body,
      hasAttachments: attachmentNames.length > 0,
      attachmentNames,
    },
  },
];

